-- N5 example sentences, batch 2: ten more topics.
--
-- Same shape as 056 and the same rule: every sentence passed `check:examples`
-- before this file existed.
--
-- Two topics that should have been in this batch are NOT here, because the
-- tokeniser cannot read their own pattern:
--
--   〜てもいい          もいい cuts as も | い | い
--   〜なければなりません  なければ cuts as な | け | れ | ば
--
-- Neither is a word the dictionary holds — they are grammar, assembled from
-- pieces — and いい is deliberately blocked besides, because 飯 "cooked rice"
-- is also read いい and would claim the spelling. A lesson whose example
-- sentences shred the very pattern they teach is worse than no lesson, so they
-- wait for the tokeniser to learn about grammar patterns. i-adjective and
-- na-adjective take their place here.
--
-- 〜が (but) is written as ますが rather than ですが throughout: です has no
-- dictionary entry and always splits into で + す, which passes unnoticed at the
-- end of a sentence and reads as shredded kana in the middle of one.
--
-- Additive, idempotent, safe on a live database.

  -- no-possessive
  ('sent-ex-no-1', 'lang-ja', '父の車です。', 'ちち の くるま です。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-no-2', 'lang-ja', '学校の先生です。', 'がっこう の せんせい です。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-no-3', 'lang-ja', '日本の音楽が好きです。', 'にほん の おんがく が すき です。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-no-4', 'lang-ja', '部屋の窓を開けます。', 'へや の まど お あけます。', 'lvl-ja-n5', 'authored', true),
  -- ka-question
  ('sent-ex-ka-1', 'lang-ja', '学生ですか。', 'がくせい です か。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-ka-2', 'lang-ja', '音楽を聞きますか。', 'おんがく お ききます か。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-ka-3', 'lang-ja', '魚が好きですか。', 'さかな が すき です か。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-ka-4', 'lang-ja', '明日来ますか。', 'あした きます か。', 'lvl-ja-n5', 'authored', true),
  -- de-location
  ('sent-ex-deloc-1', 'lang-ja', '学校で勉強します。', 'がっこう で べんきょう します。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-deloc-2', 'lang-ja', '部屋で音楽を聞きます。', 'へや で おんがく お ききます。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-deloc-3', 'lang-ja', '海で泳ぎます。', 'うみ で およぎます。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-deloc-4', 'lang-ja', '店でパンを買います。', 'みせ で パン お かいます。', 'lvl-ja-n5', 'authored', true),
  -- de-means
  ('sent-ex-demeans-1', 'lang-ja', '電車で行きます。', 'でんしゃ で いきます。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-demeans-2', 'lang-ja', '車で来ます。', 'くるま で きます。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-demeans-3', 'lang-ja', '手で作ります。', 'て で つくります。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-demeans-4', 'lang-ja', '水で洗います。', 'みず で あらいます。', 'lvl-ja-n5', 'authored', true),
  -- he-direction
  ('sent-ex-he-1', 'lang-ja', '学校へ行きます。', 'がっこう え いきます。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-he-2', 'lang-ja', '日本へ来ます。', 'にほん え きます。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-he-3', 'lang-ja', '海へ行きたいです。', 'うみ え いきたい です。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-he-4', 'lang-ja', '部屋へ入ります。', 'へや え はいります。', 'lvl-ja-n5', 'authored', true),
  -- to-with
  ('sent-ex-to-1', 'lang-ja', '友達と行きます。', 'ともだち と いきます。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-to-2', 'lang-ja', '父と話します。', 'ちち と はなします。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-to-3', 'lang-ja', '猫と遊びます。', 'ねこ と あそびます。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-to-4', 'lang-ja', '魚と肉を買います。', 'さかな と にく お かいます。', 'lvl-ja-n5', 'authored', true),
  -- ya-particle
  ('sent-ex-ya-1', 'lang-ja', '魚や肉を食べます。', 'さかな や にく お たべます。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-ya-2', 'lang-ja', '本や新聞を読みます。', 'ほん や しんぶん お よみます。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-ya-3', 'lang-ja', '山や海が好きです。', 'やま や うみ が すき です。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-ya-4', 'lang-ja', '靴や服を買います。', 'くつ や ふく お かいます。', 'lvl-ja-n5', 'authored', true),
  -- ga-but
  ('sent-ex-gabut-1', 'lang-ja', '買いますが、高いです。', 'かいます が、たかい です。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-gabut-2', 'lang-ja', '行きますが、忙しいです。', 'いきます が、いそがしい です。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-gabut-3', 'lang-ja', '魚を食べますが、肉は食べません。', 'さかな お たべます が、にく わ たべません。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-gabut-4', 'lang-ja', '泳ぎますが、寒いです。', 'およぎます が、さむい です。', 'lvl-ja-n5', 'authored', true),
  -- i-adjective
  ('sent-ex-iadj-1', 'lang-ja', '大きい山が見えます。', 'おおきい やま が みえます。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-iadj-2', 'lang-ja', '新しい車を買いました。', 'あたらしい くるま お かいました。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-iadj-3', 'lang-ja', '古い本を読みます。', 'ふるい ほん お よみます。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-iadj-4', 'lang-ja', '暑い日は水を飲みます。', 'あつい ひ わ みず お のみます。', 'lvl-ja-n5', 'authored', true),
  -- na-adjective
  ('sent-ex-naadj-1', 'lang-ja', '静かな部屋で勉強します。', 'しずかな へや で べんきょう します。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-naadj-2', 'lang-ja', '綺麗な花を買います。', 'きれいな はな お かいます。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-naadj-3', 'lang-ja', '元気な猫です。', 'げんきな ねこ です。', 'lvl-ja-n5', 'authored', true),
  ('sent-ex-naadj-4', 'lang-ja', '便利な店です。', 'べんりな みせ です。', 'lvl-ja-n5', 'authored', true)
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

SELECT g.id, s.id, 'example', s.n
FROM (VALUES
  ('no-possessive', 'sent-ex-no-1', 0),
  ('no-possessive', 'sent-ex-no-2', 1),
  ('no-possessive', 'sent-ex-no-3', 2),
  ('no-possessive', 'sent-ex-no-4', 3),
  ('ka-question', 'sent-ex-ka-1', 0),
  ('ka-question', 'sent-ex-ka-2', 1),
  ('ka-question', 'sent-ex-ka-3', 2),
  ('ka-question', 'sent-ex-ka-4', 3),
  ('de-location', 'sent-ex-deloc-1', 0),
  ('de-location', 'sent-ex-deloc-2', 1),
  ('de-location', 'sent-ex-deloc-3', 2),
  ('de-location', 'sent-ex-deloc-4', 3),
  ('de-means', 'sent-ex-demeans-1', 0),
  ('de-means', 'sent-ex-demeans-2', 1),
  ('de-means', 'sent-ex-demeans-3', 2),
  ('de-means', 'sent-ex-demeans-4', 3),
  ('he-direction', 'sent-ex-he-1', 0),
  ('he-direction', 'sent-ex-he-2', 1),
  ('he-direction', 'sent-ex-he-3', 2),
  ('he-direction', 'sent-ex-he-4', 3),
  ('to-with', 'sent-ex-to-1', 0),
  ('to-with', 'sent-ex-to-2', 1),
  ('to-with', 'sent-ex-to-3', 2),
  ('to-with', 'sent-ex-to-4', 3),
  ('ya-particle', 'sent-ex-ya-1', 0),
  ('ya-particle', 'sent-ex-ya-2', 1),
  ('ya-particle', 'sent-ex-ya-3', 2),
  ('ya-particle', 'sent-ex-ya-4', 3),
  ('ga-but', 'sent-ex-gabut-1', 0),
  ('ga-but', 'sent-ex-gabut-2', 1),
  ('ga-but', 'sent-ex-gabut-3', 2),
  ('ga-but', 'sent-ex-gabut-4', 3),
  ('i-adjective', 'sent-ex-iadj-1', 0),
