ON CONFLICT (grammar_point_id, sentence_id, role) DO NOTHING;

-- The tokens, so production gets them too.
--
-- `tokenise:authored` is a dev script and production runs migrations and
-- seeds and nothing else, so this is the only way the tokens reach it.
-- Word-order chips and cloze spans are cut from `sentence_tokens`, never
-- from the sentence text, so without these the derivation in 059 would read
-- an empty table and generate nothing.
DELETE FROM sentence_tokens WHERE sentence_id IN ('sent-ex-no-1', 'sent-ex-no-2', 'sent-ex-no-3', 'sent-ex-no-4', 'sent-ex-ka-1', 'sent-ex-ka-2', 'sent-ex-ka-3', 'sent-ex-ka-4', 'sent-ex-deloc-1', 'sent-ex-deloc-2', 'sent-ex-deloc-3', 'sent-ex-deloc-4', 'sent-ex-demeans-1', 'sent-ex-demeans-2', 'sent-ex-demeans-3', 'sent-ex-demeans-4', 'sent-ex-he-1', 'sent-ex-he-2', 'sent-ex-he-3', 'sent-ex-he-4', 'sent-ex-to-1', 'sent-ex-to-2', 'sent-ex-to-3', 'sent-ex-to-4', 'sent-ex-ya-1', 'sent-ex-ya-2', 'sent-ex-ya-3', 'sent-ex-ya-4', 'sent-ex-gabut-1', 'sent-ex-gabut-2', 'sent-ex-gabut-3', 'sent-ex-gabut-4', 'sent-ex-iadj-1', 'sent-ex-iadj-2', 'sent-ex-iadj-3', 'sent-ex-iadj-4', 'sent-ex-naadj-1', 'sent-ex-naadj-2', 'sent-ex-naadj-3', 'sent-ex-naadj-4');
